package parser
func NestedUnary() int {
	// Evaluate nested unary expression: -(-(5)) == 5
	value := 5
	negate := func(x int) int { return -x }
	return negate(negate(value))
}

package parser
import "testing"
func TestNestedUnary(t *testing.T) { if NestedUnary() != 5 { t.Fatal("nested precedence") } }
func TestBinaryForm(t *testing.T) {}
